class Solution:
    def decompressRLElist(self, nums: List[int]) -> List[int]:
        m = sum(nums[::2])
        res = [0] * m
        idx = 0
        for i in range(0, len(nums), 2):
            f, v = nums[i], nums[i + 1]
            res[idx:idx + f] = [v] * f
            idx += f
        return res

